import "server-only";

/**
 * Bundled fictional referrer forms for the demo (GET /forms/samples, GET /forms/samples/{id}/file).
 *
 * Each sample is a referrer's OWN form with its own layout, headings and questions – an MLC's Word form
 * with answer cells in tables, an insurer's fillable PDF, a case manager's heading-based Word form with
 * "Answer: ____" lines and tick boxes, and a claims handler's boxed Word form with content controls (left
 * un-mapped for the live "upload a new form" demo). The files are generated by
 * scripts/medreport/build-demo-forms.mjs into forms/samples/generated/<id>.<ext>.b64.ts (base64 modules,
 * server-only) and loaded lazily. Pre-confirmed form maps (forms/samples/maps/*.ts, bound to the file's
 * SHA-256 via generated/manifest.ts) are attached as `form` with `builtIn: true` and `sampleId`.
 *
 * Every organisation name ends with "(fictional)".
 *
 * Owner: forms-engine agent (entries and files); the ai agent may supply recorded `form` maps.
 */
import type { FormSample } from "../../api/contract";
import type { FormDefinition, FormKind, FormMimeType, ReferrerInfo } from "../../core/types";
import { sha256Hex } from "../file";
import { SAMPLE_FORM_FILES, type SampleFormFileId } from "./generated/manifest";

export interface SampleFormEntry {
  /** Stable ID, e.g. "harrow-pike-treating-physio". */
  id: string;
  title: string;
  description: string;
  referrer: ReferrerInfo;
  fileName: string;
  mimeType: FormMimeType;
  kind: FormKind;
  highlights: string[];
  /** The original file bytes (lazy import of the generated base64 module). */
  loadFile(): Promise<Uint8Array>;
  /** Pre-confirmed form map for this exact file, when one has been recorded (seeded into the library). */
  loadForm?(): Promise<FormDefinition | undefined>;
  /**
   * A pre-written map that is NOT seeded into the library: POST /forms/analyse returns it (as a
   * proposal for staff to confirm) when this exact file is uploaded and no recorded analysis exists.
   */
  loadPrewrittenAnalysis?(): Promise<FormDefinition | undefined>;
}

function bytesOf(base64: string): Uint8Array {
  return new Uint8Array(Buffer.from(base64, "base64"));
}

function fileFacts(id: SampleFormFileId, kind?: FormKind): Pick<SampleFormEntry, "fileName" | "mimeType" | "kind"> {
  const f = SAMPLE_FORM_FILES[id];
  return { fileName: f.fileName, mimeType: f.mimeType, kind: kind ?? (f.mimeType === "application/pdf" ? "pdf_acroform" : "docx") };
}

