export function getSampleForm(id: string): SampleFormEntry | undefined {
  return SAMPLE_FORMS.find((s) => s.id === id);
}

/** The sample whose file has this SHA-256 (e.g. a sample re-uploaded through POST /forms/analyse). */
export async function findSampleBySha256(sha256: string): Promise<SampleFormEntry | undefined> {
  for (const entry of SAMPLE_FORMS) {
    if (SAMPLE_FORM_FILES[entry.id as SampleFormFileId]?.sha256 === sha256) return entry;
  }
  return undefined;
}

/** Sample metadata for GET /forms/samples (hashes computed from the bytes, so they always match). */
export async function listSampleForms(): Promise<FormSample[]> {
  const samples: FormSample[] = [];
  for (const entry of SAMPLE_FORMS) {
    const bytes = await entry.loadFile();
    const sha256 = sha256Hex(bytes);
    const form = await entry.loadForm?.();
    samples.push({
      id: entry.id,
      title: entry.title,
      description: entry.description,
      referrer: entry.referrer,
      kind: entry.kind,
      file: { fileName: entry.fileName, mimeType: entry.mimeType, sha256, sizeBytes: bytes.byteLength },
      highlights: entry.highlights,
      // A recorded map is only offered for the exact file it was made from.
      ...(form && form.file.sha256 === sha256 && { form: { ...form, builtIn: true, sampleId: entry.id } }),
    });
  }
  return samples;
}
